-- Integer literals are typed as the server's int_token() (sql_lex.cc) types them: INT_NUMBER up to 2147483647,
-- LONG_NUMBER up to 9223372036854775807, ULONGLONG_NUMBER up to 18446744073709551615, DECIMAL_NUMBER above;
-- leading zeros do not count. One statement per type, in that order.
SELECT 0, 123, 999999999, 2147483647, 00000000002147483647, 000000000000;
SELECT 2147483648, 4294967295, 9999999999, 10000000000, 21474836470, 30000000000, 99999999999, 9223372036854775807, 00000000002147483648;
SELECT 9223372036854775808, 9999999999999999999, 10000000000000000000, 18446744073709551615, 0009223372036854775808;
SELECT 18446744073709551616, 99999999999999999999, 100000000000000000000, 92233720368547758070, 184467440737095516150;
-- IGNORE n LINES takes INT_NUMBER only, as the server's grammar takes NUM only.
LOAD DATA INFILE 'f' INTO TABLE t IGNORE 2147483647 LINES;
LOAD DATA INFILE 'f' INTO TABLE t IGNORE 00000000002147483647 LINES;
LOAD DATA INFILE 'f' INTO TABLE t IGNORE 000000000000 LINES;
